Command executed successfully. Output: #!/bin/bash

# env-merge.sh - Merge two .env files, second file wins on conflicts

if [[ $# -ne 2 ]]; then
    echo "Usage: $0 <file1.env> <file2.env>" >&2
    exit 1
fi

if [[ ! -f "$1" ]]; then
    echo "Error: File not found: $1" >&2
    exit 1
fi

if [[ ! -f "$2" ]]; then
    echo "Error: File not found: $2" >&2
    exit 1
fi

awk -F= '
    # Skip empty lines and comments
    /^[[:space:]]*$/ || /^[[:space:]]*#/ { next }
    # Store key=value, second file overwrites first
    {
        key = $1
        sub(/^[[:space:]]+/, "", key)
        sub(/[[:space:]]+$/, "", key)
        # Get everything after first =
        val = substr($0, index($0, "=") + 1)
        if (key != "" && index($0, "=") > 0) {
            keys[key] = val
            if (!(key in order)) {
                order[key] = ++n
            }
        }
    }
    END {
        # Output in order of first appearance
        for (i = 1; i <= n; i++) {
            for (key in order) {
                if (order[key] == i) {
                    print key "=" keys[key]
                }
            }
        }
    }
' "$1" "$2"


(exit_code=0)

